/*select id_obra, RM_NOME, RM_CODCOLIGADA, RM_CODFILIAL
from OBRA 
where ID_OBRA in (201, 203, 207, 212, 213, 215)

where id_obra = 201 then RM_CODCOLIGADA = 51
where id_obra = 203 then RM_CODCOLIGADA = 1
where id_obra = 207 then RM_CODCOLIGADA = 26
where id_obra = 212 then RM_CODCOLIGADA = 59
where id_obra = 213 then RM_CODCOLIGADA = 31
where id_obra = 215 then RM_CODCOLIGADA = 44*/

